// src/app/models/time-entry.model.ts

/**
 * Identity of the device/browser that pressed "play" for an entry. Stamped on
 * the entry at start time so a timer shared through the cloud shows WHERE it
 * was started. Any signed-in device may still stop it.
 * Optional: legacy entries and backups created before this feature won't have it.
 */
export interface EntryOrigin {
  /** Stable per-browser id (device-local; never part of backups). */
  deviceId: string;
  /** Human-friendly device label (autogenerated, e.g. "Equipo-A3F9"). */
  deviceName: string;
  /** Browser family derived from the user agent (e.g. "Chrome", "Edge"). */
  browser: string;
}

export interface TimeEntry {
  id: string;
  title: string | null;
  description: string | null;
  startTime: number; // timestamp
  endTime: number; // timestamp
  duration: number; // in milliseconds
  startedBy?: EntryOrigin; // device/browser that pressed play (optional for legacy data)
}

// Model per a l'entrada que s'està executant (endTime i duration són fixos o calculats)
export type RunningTimeEntry = Omit<TimeEntry, 'endTime' | 'duration'> & {
  endTime: null;
  duration: 0; 
};

// Type guard
export function isRunningEntry(entry: TimeEntry | RunningTimeEntry): entry is RunningTimeEntry {
  return entry.endTime === null;
}

/**
 * Best-effort repair of a stored/imported completed entry: keeps anything
 * usable (rounding times to whole ms, coercing text fields) and returns null
 * only for items the app cannot render at all. Never drops data that merely
 * looks unusual, so a legacy backup still loads.
 */
export function normalizeTimeEntry(value: unknown): TimeEntry | null {
  if (!value || typeof value !== 'object') return null;
  const e = value as Record<string, unknown>;
  const { id, startTime, endTime, duration } = e;
  if (typeof id !== 'string' || !id) return null;
  if (![startTime, endTime, duration].every(n => typeof n === 'number' && Number.isFinite(n))) return null;
  const text = (v: unknown) => (typeof v === 'string' ? v : null);
  const startedBy = e['startedBy'];
  return {
    id,
    title: text(e['title']),
    description: text(e['description']),
    startTime: Math.round(startTime as number),
    endTime: Math.round(endTime as number),
    duration: Math.round(duration as number),
    ...(startedBy && typeof startedBy === 'object' ? { startedBy: startedBy as EntryOrigin } : {}),
  };
}

/** Same as normalizeTimeEntry, for the running timer. */
export function normalizeRunningEntry(value: unknown): RunningTimeEntry | null {
  if (!value || typeof value !== 'object') return null;
  const e = value as Record<string, unknown>;
  const fixed = normalizeTimeEntry({ ...e, endTime: 0, duration: 0 });
  if (!fixed) return null;
  return { ...fixed, endTime: null, duration: 0 };
}

/**
 * Shape check for a completed entry coming from outside (a backup file). The
 * cloud stores times as bigint epoch ms, so anything non-integer would be
 * rejected by Postgres and must never reach the outbox.
 */
export function isValidTimeEntry(value: unknown): value is TimeEntry {
  if (!value || typeof value !== 'object') return false;
  const e = value as Record<string, unknown>;
  const optionalText = (v: unknown) => v === undefined || v === null || typeof v === 'string';
  return (
    typeof e['id'] === 'string' && e['id'].length > 0 &&
    Number.isSafeInteger(e['startTime']) &&
    Number.isSafeInteger(e['endTime']) &&
    Number.isSafeInteger(e['duration']) &&
    (e['endTime'] as number) >= (e['startTime'] as number) &&
    (e['duration'] as number) >= 0 &&
    optionalText(e['title']) &&
    optionalText(e['description'])
  );
}

export interface DailySummary {
  date: string; // Format 'YYYY-MM-DD'
  totalDurationMs: number;
}

export interface WeeklySummary {
  hoursWorked: number;
  horasExtra: number;      // Suma de excesos diarios > 8h
  targetHours: number;
  remainingHours: number;  // Horas pendientes solo desde hoy hasta fin de semana
  weekStart: string;       // ISO date (Monday)
  weekEnd: string;         // ISO date (Sunday)
}

export interface DayGroup {
  date: string;
  entries: TimeEntry[];
  totalDurationMs: number;
}

export interface GlobalBalance {
  balanceHours: number; // Balance total en horas (positivo = extra, negativo = falta)
}